mapper.select:
e.del_flag='0'
        and e.evaluation_type=#{evaluationType}
        and e.defect_id=#{defectId}
        and e.workpiece_id=#{workpieceId}
        and coalesce(dw.task_id,w.task_id)=#{taskId}
        and e.status=#{status}
        and exists(select 1 from ndt_inspection_task ct
            join ndt_customer cc on cc.id=ct.customer_id and cc.del_flag='0'
            where ct.id=coalesce(dw.task_id,w.task_id) and ct.customer_id=#{params.scopeCustomerId} and ct.del_flag='0')
        and exists(select 1 from ndt_task_user tu where tu.task_id=coalesce(dw.task_id,w.task_id) and tu.user_id=#{params.scopeUserId} and tu.can_view='1')
        and 1=0
    order by e.create_time desc,e.id desc
